def render(v):
 if isinstance(v,dict):return '<dl>'+''.join('<dt>'+html.escape(str(k))+'</dt><dd>'+render(x)+'</dd>'for k,x in v.items())+'</dl>'
 if isinstance(v,list):return '<ul>'+''.join('<li>'+render(x)+'</li>'for x in v)+'</ul>'
 return html.escape(str(v))
